/**
 * canvas-link command.
 *
 * Mints an embedded-canvas link for the given project and prints TWO
 * self-describing URLs so an agent picks the right one for the surface:
 *
 *   - `embedCanvasUrl` — tokenized (`?embed=1&live=1#eh=<code>`), for opening
 *     inside an agent-embedded browser (e.g. the Codex Browser panel) ONLY. It
 *     signs in automatically; the link works for about 1 hour and can be
 *     re-opened across multiple tabs, each getting its own embedded session.
 *   - `canvasUrl` — the clean canonical URL, for humans / external browsers.
 *
 * It NEVER launches a browser — it only mints and prints (the name deliberately
 * avoids "open" semantics). Minting is best-effort: on any bridge error it still
 * prints what it can and exits 0, so a link command never hard-fails.
 *
 * SECURITY: the embed code lives ONLY in the printed URL fragment — it is
 * never logged and never sent to telemetry.
 */
import { Command } from 'commander';
export declare function createCanvasLinkCommand(): Command;
